import axios from 'axios';

const api = axios.create({
  baseURL: process.env.REACT_APP_API_URL || 'http://localhost:8000/api',
  headers: { 'Content-Type': 'application/json' },
  timeout: 10000,
});

api.interceptors.response.use(
  (response) => response,
  (error) => {
    const message =
      error.response?.data?.message ||
      error.response?.data?.error ||
      'Une erreur est survenue';
    return Promise.reject(new Error(message));
  }
);

// ── Mock users (supprimer quand le backend est prêt) ─────────────────────────
const MOCK_USERS = [
  { id: 1, name: 'Admin Principal',  email: 'admin@hotel.com',       password: 'Admin123!',  role: 'admin' },
  { id: 2, name: 'Sophie Martin',    email: 'reception@hotel.com',   password: 'Recep123!',  role: 'receptionist' },
  { id: 3, name: 'Jean Dupont',      email: 'client@hotel.com',      password: 'Client123!', role: 'client' },
];

const authService = {
  login: async ({ email, password }) => {
    await new Promise(r => setTimeout(r, 600));
    const user = MOCK_USERS.find(u => u.email === email && u.password === password);
    if (!user) throw new Error('Email ou mot de passe incorrect');
    const { password: _, ...safeUser } = user;
    return { token: `mock-token-${user.role}-${Date.now()}`, user: safeUser };
  },

  register: async ({ name, email, phone, password }) => {
    await new Promise(r => setTimeout(r, 600));
    if (MOCK_USERS.find(u => u.email === email))
      throw new Error('Cet email est déjà utilisé');
    const newUser = { id: Date.now(), name, email, phone, role: 'client' };
    return { token: `mock-token-client-${Date.now()}`, user: newUser };
  },

  setAuthHeader: (token) => {
    api.defaults.headers.common['Authorization'] = `Bearer ${token}`;
  },

  removeAuthHeader: () => {
    delete api.defaults.headers.common['Authorization'];
  },
};

export { api };
export default authService;
